const seen = new Map<string, string>();
return occurrences.reduce((diagnostics, occurrence) => {
  const { id, file } = occurrence;
  if (seen.has(id)) {
    diagnostics.push({ code: "OARC-E011", file, id });
  } else {
    seen.set(id, file);
  }
  return diagnostics;
}, [] as Diagnostic[]);
